import { describe, test } from 'node:test'
import assert from 'node:assert/strict'
import DUT from '@/cloud/devices/VCCHL2QEUK'
import type { Metadata } from '@/cloud/thinq'
import { MockHAConnection, MockThinq2Device, buf } from '@/tests/helpers/mocks'

const DEVICE_ID = 'test-id'
const MODEL_ID = 'VCCHL2QEUK'
const META: Metadata = { modelId: MODEL_ID, modelName: 'VCCHL2QEUK', swVersion: '3.0.28' }

// Real frames from an LG WHX9016TLC, 2026-11-09: a pass along the programme dial from TurboWash 39 and
// through the timed dry levels, then the door opened and shut.

// The status request answered: Ready on TurboWash 39, 40 C, 1200 rpm, 39 min, TurboWash on.
const READY_TURBOWASH_39 = buf(
    'AAFF200A005900001B000100EB00470003030E087A00000000000000002700270000007A010000090000011F020000000020000002000418000000000000040000000000000000000000006400041000000000000004C3ACBB',
)
// The dial moved from Timed Dry to AI Wash+Dry: 40 C, 1400 rpm, dry level Cupboard, 316 min.
const PAIR_AI_WASH_DRY = buf(
    '',
)
// Timed Dry, the level stepped from 20 to 30 min: no temperature, drain only.
const PAIR_TIMED_DRY_30 = buf(
    '',
)
// The machine switching itself off at Ready.
const PAIR_OFF = buf(
    '',
)
// Door events: opened, then shut.
const DOOR_OPENED = buf(
    'AAFF200A0041000084000201030006100E0602100101050025564343484C325145554B000000000000000000000102BB9483C40607000000000000000000CCF0BB',
)
const DOOR_CLOSED = buf(
    'AAFF200A0041000085000201030006100E0602100201050025564343484C325145554B000000000000000000000102BF9483C406070000000000000000009071BB',
)
// The power-on event, which is not the door's.
const POWER_ON_EVENT = buf(
    'AAFF200A004100001C000201030006110E0602110401050025564343484C325145554B000000000000000000000102C09483C40607000000000000000000D5FCBB',
)

// A TurboWash 39 at 30 C and 800 rpm, started at the panel: half a minute of PRODUCT_STANDBY...
const PAIR_STARTING = buf(
    '',
)
// ...then the wash.
const PAIR_WASHING = buf(
    '',
)

// A Timed Dry at 40 min, 34 minutes in: 315 Wh, the count past one byte...
const PAIR_DRYING = buf(
    '',
)
// ...the last five minutes, in a state the modelJSON does not list...
const PAIR_COOLING = buf(
    '',
)
// ...and the end, the drum-clean count stepped to 33.
const PAIR_DRY_END = buf(
    '',
)

// 2026-11-12, Cotton at the panel: Pre Wash on, then off...
const PAIR_PREWASH_ON = buf(
    '',
)
const PAIR_PREWASH_OFF = buf(
    '',
)
// ...the child lock on and off (CL on the display)...
const PAIR_CHILD_LOCK_ON = buf(
    '',
)
const PAIR_CHILD_LOCK_OFF = buf(
    '',
)
// ...Delay End set to 3 h, then cancelled...
const PAIR_DELAY_3H = buf(
    '',
)
const PAIR_DELAY_OFF = buf(
    '',
)
// ...and Remote Start switched on, at Spin Only.
const PAIR_REMOTE_START_ON = buf(
    '',
)
// 2026-11-12, powered on at Timed Dry: the first record has no programme times yet...
const POWER_ON_STANDBY = buf(
    'AAFF200A0059000CDC000100EB0047000000000C53130000000000000000000000000053010000090000000002000000000000004000041800000000000004000000000000000000000000640004100000010000000433FFBB',
)
// ...the next, a second later, has them.
const PAIR_POWER_ON_TIMES = buf(
    '',
)

// 2026-11-17, Cotton: the rinse option pressed through its six positions, back to Normal.
const PAIR_RINSE_PLUS = buf(
    '',
)
const PAIR_RINSE_PLUS2 = buf(
    '',
)
const PAIR_RINSE_HOLD = buf(
    '',
)
const PAIR_RINSE_PLUS_HOLD = buf(
    '',
)
const PAIR_NO_RINSE = buf(
    '',
)
const PAIR_RINSE_NORMAL = buf(
    '',
)

// 2026-11-17, Cotton: the soil level stepped from Medium to Heavy, Light and back...
const PAIR_SOIL_HEAVY = buf(
    '',
)
const PAIR_SOIL_LIGHT = buf(
    '',
)
const PAIR_SOIL_MEDIUM = buf(
    '',
)
// ...then Steam on and off...
const PAIR_STEAM_ON = buf(
    '',
)
const PAIR_STEAM_OFF = buf(
    '',
)
// ...and Wrinkle care on and off.
const PAIR_WRINKLE_CARE_ON = buf(
    '',
)
const PAIR_WRINKLE_CARE_OFF = buf(
    '',
)

// The ThinQ app's commands, as the LG cloud sent them through the bridge.
const WRITE_POWER_ON = 'AA08F0A1010011BB'
const WRITE_POWER_OFF = 'AA0DF0E5000201FF010200C4BB'
const WRITE_START = 'AA0DF0E5000201FF010301C6BB'
const WRITE_PAUSE = 'AA0DF0E5000201FF010302C1BB'

function makeDevice() {
    const ha = new MockHAConnection()
    const thinq = new MockThinq2Device(DEVICE_ID, META)
    const dev = new DUT(ha.asConnection(), thinq, META)
    return { ha, thinq, dev, props: () => ha.devices[DEVICE_ID].properties }
}

describe(MODEL_ID, () => {
    test('asks for the status on connect', () => {
        const { thinq, dev } = makeDevice()
        dev.start()
        assert.deepEqual(
            thinq.outbox.map((b) => b.toString('hex').toUpperCase()),
            ['AA0EF0ED1121010000001800B5BB'],
        )
    })

    test('the 0xeb answer decodes the selected programme', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', READY_TURBOWASH_39)
        assert.equal(props().power, 'ON')
        assert.equal(props().status, 'Standby')
        assert.equal(props().course, 'TurboWash 39')
        assert.equal(props().temp, '40 °C')
        assert.equal(props().spin, '1200 rpm')
        assert.equal(props().rinse, 'Normal')
        assert.equal(props().dry_level, 'Off')
        assert.equal(props().initial_time, 39)
        assert.equal(props().remaining_time, 39)
        assert.equal(props().turbowash, 'ON')
        assert.equal(props().prewash, 'OFF')
        assert.equal(props().tub_clean_count, 31)
        assert.equal(props().energy, 0)
    })

    test('a wash+dry programme, with its time past 255 minutes', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_AI_WASH_DRY)
        assert.equal(props().course, 'AI Wash+Dry')
        assert.equal(props().temp, '40 °C')
        assert.equal(props().spin, '1400 rpm')
        assert.equal(props().dry_level, 'Cupboard')
        assert.equal(props().initial_time, 316)
        assert.equal(props().remaining_time, 316)
        assert.equal(props().turbowash, 'OFF')
    })

    test('a drying programme and its timed level', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_TIMED_DRY_30)
        assert.equal(props().course, 'Timed Dry')
        assert.equal(props().temp, 'Off')
        assert.equal(props().spin, 'Drain only')
        assert.equal(props().rinse, 'Not selected')
        assert.equal(props().soil, 'Off')
        assert.equal(props().dry_level, '30 min')
        assert.equal(props().remaining_time, 30)
    })

    test('power off clears the settings', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', READY_TURBOWASH_39)
        thinq.emit('data', PAIR_OFF)
        assert.equal(props().power, 'OFF')
        assert.equal(props().status, 'Off')
        assert.equal(props().course, 'None') // unknown in HA
        assert.equal(props().remaining_time, 'None')
        assert.equal(props().tub_clean_count, 31) // kept from when it was on
    })

    test('the first record after power-on publishes no programme times', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', POWER_ON_STANDBY)
        assert.equal(props().power, 'ON')
        assert.equal(props().status, 'Standby')
        assert.equal(props().course, 'Timed Dry')
        assert.equal(props().remaining_time, undefined)
        assert.equal(props().initial_time, undefined)
        assert.equal(props().tub_clean_count, undefined)

        thinq.emit('data', PAIR_POWER_ON_TIMES)
        assert.equal(props().remaining_time, 20)
        assert.equal(props().initial_time, 20)
        assert.equal(props().tub_clean_count, 39)
    })

    test('the door comes in event frames', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', POWER_ON_EVENT)
        assert.equal(props().door, undefined)
        thinq.emit('data', DOOR_OPENED)
        assert.equal(props().door, 'ON')
        thinq.emit('data', DOOR_CLOSED)
        assert.equal(props().door, 'OFF')
    })

    test('a wash started at the panel', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_STARTING)
        assert.equal(props().status, 'Starting')
        assert.equal(props().temp, '30 °C')
        assert.equal(props().spin, '800 rpm')
        assert.equal(props().remaining_time, 38)
        assert.equal(props().remote_start, 'ON') // a panel start sets it, as on G2V7
        assert.equal(props().door, undefined) // not published: no door event yet

        thinq.emit('data', PAIR_WASHING)
        assert.equal(props().status, 'Washing')
        assert.equal(props().door, 'OFF') // locked shut while it runs
    })

    test('a timed dry, through the cool-down to the end', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_DRYING)
        assert.equal(props().status, 'Drying')
        assert.equal(props().dry_level, '40 min')
        assert.equal(props().remaining_time, 6)
        assert.equal(props().initial_time, 40)
        assert.equal(props().energy, 315)
        assert.equal(props().door, 'OFF')

        thinq.emit('data', PAIR_COOLING)
        assert.equal(props().status, 'Cooling')
        assert.equal(props().remaining_time, 5)
        assert.equal(props().energy, 328)

        thinq.emit('data', PAIR_DRY_END)
        assert.equal(props().status, 'End')
        assert.equal(props().remaining_time, 0)
        assert.equal(props().energy, 331)
        assert.equal(props().tub_clean_count, 33)
    })

    test('options set and cleared at the panel', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_PREWASH_ON)
        assert.equal(props().course, 'Cotton')
        assert.equal(props().prewash, 'ON')
        assert.equal(props().remaining_time, 239)
        thinq.emit('data', PAIR_PREWASH_OFF)
        assert.equal(props().prewash, 'OFF')
        assert.equal(props().remaining_time, 222)

        thinq.emit('data', PAIR_CHILD_LOCK_ON)
        assert.equal(props().child_lock, 'OFF') // locked: device_class lock is inverted
        thinq.emit('data', PAIR_CHILD_LOCK_OFF)
        assert.equal(props().child_lock, 'ON')

        thinq.emit('data', PAIR_DELAY_3H)
        assert.equal(props().delay_end, 180)
        thinq.emit('data', PAIR_DELAY_OFF)
        assert.equal(props().delay_end, 0)

        thinq.emit('data', PAIR_REMOTE_START_ON)
        assert.equal(props().course, 'Spin Only')
        assert.equal(props().remote_start, 'ON')
    })

    test('the rinse options, one press at a time', () => {
        const { thinq, props } = makeDevice()
        const steps: [Buffer, string][] = [
            [PAIR_RINSE_PLUS, 'Rinse+'],
            [PAIR_RINSE_PLUS2, 'Rinse++'],
            [PAIR_RINSE_HOLD, 'Normal + Hold'],
            [PAIR_RINSE_PLUS_HOLD, 'Rinse+ + Hold'],
            [PAIR_NO_RINSE, 'Not selected'],
            [PAIR_RINSE_NORMAL, 'Normal'],
        ]
        for (const [frame, rinse] of steps) {
            thinq.emit('data', frame)
            assert.equal(props().rinse, rinse)
        }
    })

    test('soil level, steam and wrinkle care, set at the panel', () => {
        const { thinq, props } = makeDevice()
        thinq.emit('data', PAIR_SOIL_HEAVY)
        assert.equal(props().soil, 'Heavy')
        assert.equal(props().initial_time, 244)
        thinq.emit('data', PAIR_SOIL_LIGHT)
        assert.equal(props().soil, 'Light')
        assert.equal(props().initial_time, 191)
        thinq.emit('data', PAIR_SOIL_MEDIUM)
        assert.equal(props().soil, 'Medium')

        thinq.emit('data', PAIR_STEAM_ON)
        assert.equal(props().steam, 'ON')
        assert.equal(props().temp, '60 °C') // Steam raised it from 40 °C
        thinq.emit('data', PAIR_STEAM_OFF)
        assert.equal(props().steam, 'OFF')
        assert.equal(props().temp, '40 °C')

        thinq.emit('data', PAIR_WRINKLE_CARE_ON)
        assert.equal(props().wrinkle_care, 'ON')
        thinq.emit('data', PAIR_WRINKLE_CARE_OFF)
        assert.equal(props().wrinkle_care, 'OFF')
    })

    test('commands', () => {
        const { thinq, dev } = makeDevice()
        const sent = () => thinq.outbox.map((b) => b.toString('hex').toUpperCase())
        dev.setProperty('power', 'ON')
        dev.setProperty('power', 'OFF')
        dev.setProperty('start', '')
        dev.setProperty('pause', '')
        assert.deepEqual(sent(), [WRITE_POWER_ON, WRITE_POWER_OFF, WRITE_START, WRITE_PAUSE])
    })

    test('every envelope is acked by its sequence number', () => {
        const { thinq } = makeDevice()
        thinq.emit('data', READY_TURBOWASH_39)
        thinq.emit('data', DOOR_OPENED)
        const acks = thinq.sent.filter((m) => m.cmd === 'ack').map((m) => String(m.data))
        assert.equal(acks.length, 2)
        assert.match(acks[0], /^AA0AF0000A04001B..BB$/)
        assert.match(acks[1], /^AA0AF0000A040084..BB$/)
    })
})
